#!/usr/bin/env python3
"""ioc_sweep.py - read-only sweep of a folder and a log file for known IOCs.
Usage: python3 ioc_sweep.py iocs.txt <folder> <logfile>"""
import hashlib
import ipaddress
import re
import sys
from pathlib import Path


def load_iocs(path):
    iocs = {"sha256": set(), "ip": set(), "domain": set()}
    for raw in Path(path).read_text().splitlines():
        line = raw.strip().lower().replace("[.]", ".")   # re-fang 'evil[.]example'
        if not line or line.startswith("#"):
            continue
        if re.fullmatch(r"[0-9a-f]{64}", line):
            iocs["sha256"].add(line)
            continue
        try:
            ipaddress.ip_address(line)
            iocs["ip"].add(line)
        except ValueError:
            iocs["domain"].add(line)
    return iocs


def sha256_of(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main(ioc_file, folder, log_file):
    iocs = load_iocs(ioc_file)
    hits = 0
    for p in Path(folder).rglob("*"):                # 1. file hashes
        if p.is_file():
            try:
                digest = sha256_of(p)
            except OSError:
                continue
            if digest in iocs["sha256"]:
                print(f"[HASH] {p}  sha256={digest[:16]}...")
                hits += 1
    lines = Path(log_file).read_text(errors="ignore").splitlines()
    for n, line in enumerate(lines, 1):              # 2. IPs and domains in logs
        for token in re.findall(r"[a-z0-9.-]+", line.lower()):
            if token in iocs["ip"] or any(
                token == d or token.endswith("." + d) for d in iocs["domain"]
            ):
                print(f"[LOG]  {log_file}:{n}  {token}")
                hits += 1
    print(f"Sweep complete: {len(iocs['sha256'])} hashes, {len(iocs['ip'])} IPs, "
          f"{len(iocs['domain'])} domains checked - {hits} hit(s)")


if __name__ == "__main__":
    if len(sys.argv) != 4:
        sys.exit(__doc__)
    main(*sys.argv[1:4])

